"""Rebuild AGR's scoped records from the inspected evidence described in report.md.

This script performs no source retrieval. It preserves the distinction between
observations, estimates, historical interpretations and proposed tests.
"""
from pathlib import Path
import json

OUT = Path(__file__).resolve().parent


def ident(kind, number):
    return f"AGR-{kind}{number:02d}"


def refs(kind, numbers):
    return [ident(kind, n) for n in numbers]


def test(status, chain, rival, observation, found, ambiguity,
         timing="retrospective synthesis"):
    return {
        "status": status,
        "mechanism_chain": chain,
        "strongest_rival": rival,
        "discriminating_observation": observation,
        "evidence_sought_found": found,
        "remaining_ambiguity": ambiguity,
        "hypothesis_timing": timing,
    }


def descriptive(reason):
    return {"status": "descriptive-only", "reason": reason}


def claim(n, cases, statement, evidence, confidence, causal, supports,
          counterevidence, limits, diagnostic):
    return {
        "id": ident("K", n), "case_ids": refs("C", cases),
        "statement": statement, "evidence_type": evidence,
        "confidence": confidence, "causal_status": causal,
        "sources": [
            {"source_id": ident("S", s), "locator": locator, "supports": content}
            for s, locator, content in supports
        ],
        "counterevidence": counterevidence, "inference_limits": limits,
        "test": diagnostic,
    }


