def case(n, title, region, period, domain, outcome, summary, stages,
         mechanisms, counterevidence, ks, ss, episode, actors, labour):
    return {
        "id": ident("C", n), "title": title, "region": region, "period": period,
        "domain": domain, "outcome": outcome, "summary": summary,
        "stages": stages, "mechanisms": mechanisms,
        "counterevidence": counterevidence, "claim_ids": refs("K", ks),
        "source_ids": refs("S", ss), "episode": episode, "actors": actors,
        "labour": labour,
    }


