def edge(n, origin, target, relation, case_number, ks, ss, confidence,
         qualification, basis, stage, configuration, alternatives, dispute,
         joint_inputs=()):
    return {
        "id": ident("E", n), "from": ident("T", origin),
        "to": ident("T", target), "relation": relation,
        "case_ids": refs("C", [case_number]), "claim_ids": refs("K", ks),
        "source_ids": refs("S", ss), "confidence": confidence,
        "qualification": qualification, "basis": basis,
        "scope": {"case_id": ident("C", case_number), "stage": stage,
                  "configuration": configuration},
        "alternatives": alternatives, "joint_inputs": refs("T", joint_inputs),
        "necessity_rationale": "No necessity claim", "dispute": dispute,
    }


