def validate_local():
    sources = json.loads((OUT / "sources.json").read_text())
    groups = {"cases": cases, "claims": claims, "sources": sources,
              "nodes": nodes, "edges": edges, "comparisons": comparisons}
    all_ids = [item["id"] for values in groups.values() for item in values]
    assert len(all_ids) == len(set(all_ids)), "Duplicate IDs"
    index = {name: {item["id"]: item for item in values}
             for name, values in groups.items()}
    for name, values in groups.items():
        for item in values:
            for field, target in [("case_ids", "cases"), ("claim_ids", "claims"),
                                  ("source_ids", "sources")]:
                for value in item.get(field, []):
                    assert value in index[target], (item["id"], field, value)
    for c in claims:
        assert c["sources"], c["id"]
        for support in c["sources"]:
            assert support["source_id"] in index["sources"], c["id"]
            assert support["locator"] and support["supports"], c["id"]
        if c["test"]["status"] == "descriptive-only":
            assert c["causal_status"] == "descriptive", c["id"]
        else:
            assert c["causal_status"] != "descriptive", c["id"]
            for field in ["mechanism_chain", "strongest_rival",
                          "discriminating_observation", "evidence_sought_found",
                          "remaining_ambiguity", "hypothesis_timing"]:
                assert c["test"].get(field), (c["id"], field)
    for e in edges:
        assert e["from"] in index["nodes"] and e["to"] in index["nodes"], e["id"]
        assert e["scope"]["case_id"] in e["case_ids"], e["id"]
        for n in e["joint_inputs"]:
            assert n in index["nodes"], (e["id"], n)
        if e["relation"] == "depends-on":
            assert e["basis"] == "bounded-necessity", e["id"]
        support_sources = {s["source_id"] for k in e["claim_ids"]
                           for s in index["claims"][k]["sources"]}
        assert set(e["source_ids"]) <= support_sources, e["id"]
    for c in cases:
        for field, required in {
            "episode": ["technology_configuration", "task", "population", "interval",
                        "contemporary_alternatives", "adoption_measure", "observation_limits"],
            "actors": ["chooser", "payer", "operator_maintainer", "affected_nonchooser",
                       "ability_to_refuse"],
            "labour": ["tasks", "entry_barriers", "bargaining_ownership", "transition",
                       "distribution", "evidence_limit"],
        }.items():
            assert all(c[field].get(k) for k in required), (c["id"], field)
        for k in c["claim_ids"]:
            assert c["id"] in index["claims"][k]["case_ids"], (c["id"], k)
    for s in sources:
        assert s.get("evidence_lineage"), s["id"]
    report = (OUT / "report.md").read_text()
    for c in cases:
        assert c["id"] in report, c["id"]
    return {name: len(values) for name, values in groups.items()}


if __name__ == "__main__":
    counts = validate_local()
    save("cases.json", cases)
    save("claims.json", claims)
    save("graph.json", {
        "nodes": nodes, "edges": edges,
        "semantics": "Scoped typed multigraph. No edge is transitive across episodes. Empty joint_inputs means no bundle claim, not sufficiency. The disconnected ancient-field node deliberately avoids asserting transmission from ancient use to modern revival. No seed-specific edge to groundwater depletion is supported.",
    })
    save("comparisons.json", comparisons)
    print(json.dumps({"local_validation": "passed", "counts": counts}, indent=2))

